17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    /** Dedicated audit trail logger; carries a line for each successful owner create. */
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
103	     *  separated by '@', none of which contain whitespace or a second '@'. */
104	    private static final java.util.regex.Pattern EMAIL_PATTERN =
105	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
106	
107	    /** Disposable email domains that are not accepted as an owner's email. */
108	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
109	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
110	
111	    /**
112	     * Normalize the optional email: absent stays absent; when present it must be syntactically
113	     * valid and is lower-cased. Returns {@code false} if present but invalid, including when its
114	     * domain is on the disposable-domain blocklist.
115	     */
116	    private boolean normalizeEmail(Owner owner) {
117	        String email = owner.getEmail();
118	        if (email == null || email.isEmpty()) {
119	            owner.setEmail(null);
120	            return true;
121	        }
122	        if (!EMAIL_PATTERN.matcher(email).matches()) {
123	            return false;
124	        }
125	        email = email.toLowerCase(java.util.Locale.ROOT);
126	        String domain = email.substring(email.indexOf('@') + 1);
127	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
128	            return false;
129	        }
130	        owner.setEmail(email);
131	        return true;
132	    }
133	
134	    /**
135	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
136	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
137	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
138	     *
139	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
140	     *         a valid E.164 number.
141	     */
142	    private static String toE164(String raw) {
143	        if (raw == null) {
144	            return null;
145	        }
146	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
147	        String digits;
148	        if (cleaned.startsWith("+")) {
149	            digits = cleaned.substring(1);
150	        } else {
151	            if (cleaned.startsWith("0")) {
152	                cleaned = cleaned.substring(1);
153	            }
154	            digits = "61" + cleaned;
155	        }
156	        if (!digits.matches("\\d{8,15}")) {
157	            return null;
158	        }
159	        return "+" + digits;
160	    }
161	
162	    /**
163	     * Validate the national-number length of a canonical E.164 string against its country code:
164	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
165	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
166	     * string produced by {@link #toE164}.
167	     *
168	     * @return {@code true} when the national-number length is correct for the country code.
169	     */
170	    private static boolean hasValidNationalLength(String e164) {
171	        String digits = e164.substring(1);
172	        if (digits.startsWith("61")) {
173	            return digits.length() - 2 == 9;
174	        }
175	        if (digits.startsWith("1")) {
176	            return digits.length() - 1 == 10;
177	        }
178	        return true;
179	    }
180	
181	    /**
182	     * Build the customer code {@code <REGION>-<HASH8>}: REGION is the region code derived from the
183	     * owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN} when the postcode is absent or in no known
184	     * range) and HASH8 is the first 8 upper-case hex characters of SHA-256 over the concatenation of
185	     * the owner's normalized (E.164) telephone and last name (e.g. {@code NSW-3F9A0C17}). No sequence
186	     * numbers are used, so the code is a pure function of the owner's region-and-hash identity.
187	     */
188	    private String customerCodeFor(Owner owner) {
189	        String region = ownerMapper.regionFromPostcode(owner);
190	        if (region == null) {
191	            region = "UNKNOWN";
192	        }
193	        return region + "-" + hash8(owner.getTelephone(), owner.getLastName());
194	    }
195	
196	    /**
197	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
198	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
199	     */
200	    private static String hash8(String normalizedTelephone, String lastName) {
201	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
202	            + (lastName == null ? "" : lastName);
203	        try {
204	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
205	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
206	            StringBuilder sb = new StringBuilder(8);
207	            for (int i = 0; i < 4; i++) {
208	                sb.append(String.format("%02X", digest[i]));
209	            }
210	            return sb.toString();
211	        }
212	        catch (java.security.NoSuchAlgorithmException e) {
213	            throw new IllegalStateException(e);
214	        }
215	    }
216	
217	    /** Common street-type abbreviations expanded during address normalization. */
218	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
219	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
220	
221	    /**
222	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
223	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
224	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
225	     */
226	    private static String normalizeAddress(String value) {
227	        if (value == null) {
228	            return "";
229	        }
230	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
231	        if (collapsed.isEmpty()) {
232	            return "";
233	        }
234	        String[] tokens = collapsed.split(" ");
235	        StringBuilder sb = new StringBuilder(collapsed.length());
236	        for (int i = 0; i < tokens.length; i++) {
237	            if (i > 0) {
238	                sb.append(' ');
239	            }
240	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
241	        }
242	        return sb.toString();
243	    }
244	
245	    /**
246	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
247	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
248	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
249	     */
250	    private static String normalizeForHousehold(String value) {
251	        if (value == null) {
252	            return "";
253	        }
254	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
255	    }
256	
257	    /**
258	     * Return the owners that already share this owner's household, i.e. resolve to the same
259	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
260	     * postcode).
261	     */
262	    private List<Owner> householdMembers(Owner owner) {
263	        String householdId = householdIdFor(owner);
264	        List<Owner> members = new java.util.ArrayList<>();
265	        for (Owner existing : this.clinicService.findAllOwners()) {
266	            if (householdId.equals(householdIdFor(existing))) {
267	                members.add(existing);
268	            }
269	        }
270	        return members;
271	    }
272	
273	    /**
274	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
275	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
276	     */
277	    private boolean sharesHouseholdWithExisting(Owner owner) {
278	        return !householdMembers(owner).isEmpty();
279	    }
280	
281	    /**
282	     * Count the existing owners that share this owner's first name and last name, compared
283	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
284	     */
285	    private int namesakeCount(Owner owner) {
286	        String firstName = owner.getFirstName();
287	        String lastName = owner.getLastName();
288	        int count = 0;
289	        for (Owner existing : this.clinicService.findAllOwners()) {
290	            if (firstName != null && lastName != null
291	                && firstName.equalsIgnoreCase(existing.getFirstName())
292	                && lastName.equalsIgnoreCase(existing.getLastName())) {
293	                count++;
294	            }
295	        }
296	        return count;
297	    }
298	
299	    /**
300	     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
301	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes an empty string).
302	     * Because it is a pure function of the last name and postcode, every owner in the same household
303	     * deterministically resolves to the same value.
304	     */
305	    private static String householdIdFor(Owner owner) {
306	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
307	        String key = normalizeForHousehold(owner.getLastName()) + "|" + postcode;
308	        try {
309	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
310	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
311	            StringBuilder sb = new StringBuilder(12);
312	            for (int i = 0; i < 6; i++) {
313	                sb.append(String.format("%02X", digest[i]));
314	            }
315	            return sb.toString();
316	        }
317	        catch (java.security.NoSuchAlgorithmException e) {
318	            throw new IllegalStateException(e);
319	        }
320	    }
321	
322	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
323	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
324	        "NSW", new int[] {2000, 2099},
325	        "VIC", new int[] {3000, 3099},
326	        "QLD", new int[] {4000, 4099});
327	
328	    /**
329	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
330	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
331	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
332	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
333	     * postcode.
334	     */
335	    private boolean isPostcodeValid(Owner owner) {
336	        String postcode = owner.getPostcode();
337	        if (postcode == null || postcode.isEmpty()) {
338	            return true;
339	        }
340	        if (!postcode.matches("\\d{4}")) {
341	            return false;
342	        }
343	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
344	        if (range == null) {
345	            return true;
346	        }
347	        int value = Integer.parseInt(postcode);
348	        return value >= range[0] && value <= range[1];
349	    }
350	
351	    /**
352	     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
353	     * "possible duplicate": one that shares the owner's last name (case-insensitive) and postcode
354	     * but carries a different (normalized) telephone. When several match, the one with the smallest
355	     * id is chosen so the result is deterministic. Returns {@code null} when the owner has no
356	     * postcode or no such existing owner exists.
357	     */
358	    private Owner possibleDuplicateOf(Owner owner) {
359	        String lastName = owner.getLastName();
360	        String postcode = owner.getPostcode();
361	        String telephone = owner.getTelephone();
362	        if (lastName == null || postcode == null || postcode.isEmpty()) {
363	            return null;
364	        }
365	        Owner match = null;
366	        for (Owner existing : this.clinicService.findAllOwners()) {
367	            if (lastName.equalsIgnoreCase(existing.getLastName())
368	                && postcode.equals(existing.getPostcode())
369	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
370	                if (match == null || (existing.getId() != null && match.getId() != null
371	                    && existing.getId() < match.getId())) {
372	                    match = existing;
373	                }
374	            }
375	        }
376	        return match;
377	    }
378	
379	    /** Maximum number of owners permitted in a single city. */
380	    private static final int CITY_CAPACITY = 50;
381	
382	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
383	    private static final int DAILY_CREATE_LIMIT = 100;
384	
385	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
386	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
387	
388	    /**
389	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
390	     * Used to enforce the per-city capacity on create (before this owner is saved).
391	     */
392	    private int cityOwnerCount(Owner owner) {
393	        String city = owner.getCity();
394	        int count = 0;
395	        for (Owner existing : this.clinicService.findAllOwners()) {
396	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
397	                count++;
398	            }
399	        }
400	        return count;
401	    }
402	
403	    /**
404	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
405	     * following Monday, any weekday is returned unchanged. Applied to the effective registration date
406	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
407	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
408	     */
409	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
410	        switch (date.getDayOfWeek()) {
411	            case SATURDAY:
412	                return date.plusDays(2);
413	            case SUNDAY:
414	                return date.plusDays(1);
415	            default:
416	                return date;
417	        }
418	    }
419	
420	    /**
421	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
422	     * per-day create limit on create (before this owner is saved).
423	     */
424	    private int ownersRegisteredOn(java.time.LocalDate day) {
425	        int count = 0;
426	        for (Owner existing : this.clinicService.findAllOwners()) {
427	            if (day.equals(existing.getRegistrationDate())) {
428	                count++;
429	            }
430	        }
431	        return count;
432	    }
433	
434	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
435	    @Override
436	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
437	        HttpHeaders headers = new HttpHeaders();
438	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
439	        if (!isPostcodeValid(owner)) {
440	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
441	        }
442	        String telephone = toE164(owner.getTelephone());
443	        if (telephone == null || !hasValidNationalLength(telephone)) {
444	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
445	        }
446	        if (!normalizeEmail(owner)) {
447	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
448	        }
449	        String address = normalizeAddress(owner.getAddress());
450	        if (address.isEmpty()) {
451	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
452	        }
453	        owner.setAddress(address);
454	        owner.setTelephone(telephone);
455	        if (owner.getRegistrationDate() != null
456	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
457	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
458	        }
459	        java.time.LocalDate registrationDate = toBusinessDay(
460	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
461	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
462	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
463	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
464	        }
465	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
466	            return new ResponseEntity<>(HttpStatus.CONFLICT);
467	        }
468	        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
469	        // owners with the same last name and postcode automatically share it. The link is no longer
470	        // created by copying an existing owner's id around.
471	        owner.setHouseholdId(householdIdFor(owner));
472	        List<Owner> householdMembers = householdMembers(owner);
473	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
474	        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();
475	
476	        // Hard duplicate: a new owner whose WHOLE identityKey (telephone|email|householdId) equals an
477	        // existing owner's is a byte-for-byte identity match and is always rejected.
478	        String identityKey = owner.getIdentityKey();
479	        for (Owner existing : this.clinicService.findAllOwners()) {
480	            if (identityKey.equals(existing.getIdentityKey())) {
481	                return new ResponseEntity<>(HttpStatus.CONFLICT);
482	            }
483	        }
484	        // Household duplicate: another owner already shares this (last name, postcode) household.
485	        // Rejected as a duplicate unless the caller sets 'sharesHousehold', which now only bypasses
486	        // this block (the shared householdId itself is already assigned deterministically above).
487	        if (!householdMembers.isEmpty() && !sharesHousehold) {
488	            return new ResponseEntity<>(HttpStatus.CONFLICT);
489	        }
490	        // A declared household member is not a suspected duplicate. Otherwise, flag an owner that
491	        // shares an existing owner's last name and postcode with a different telephone.
492	        if (declaredHouseholdMember) {
493	            owner.setPossibleDuplicate(false);
494	            owner.setPossibleDuplicateOf(null);
495	        }
496	        else {
497	            Owner duplicateOf = possibleDuplicateOf(owner);
498	            owner.setPossibleDuplicate(duplicateOf != null);
499	            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
500	        }
501	        owner.setNamesakeCount(namesakeCount(owner));
502	        owner.setHouseholdSize(householdMembers.size() + 1);
503	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
504	        owner.setRegistrationDate(registrationDate);
505	        owner.setCustomerCode(customerCodeFor(owner));
506	        this.clinicService.saveOwner(owner);
507	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
508	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
509	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
510	        headers.setLocation(UriComponentsBuilder.newInstance()
511	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
512	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
513	    }
514	
515	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
516	    @Override
517	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
518	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
519	        if (currentOwner == null) {
520	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
521	        }
522	        currentOwner.setAddress(ownerFieldsDto.getAddress());
523	        currentOwner.setCity(ownerFieldsDto.getCity());
524	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
525	        currentOwner.setLastName(ownerFieldsDto.getLastName());
526	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
527	        currentOwner.setEmail(ownerFieldsDto.getEmail());
528	        if (!normalizeEmail(currentOwner)) {
529	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
530	        }
531	        this.clinicService.saveOwner(currentOwner);
532	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
533	    }
534	
535	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
536	    @Transactional
537	    @Override
538	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
539	        Owner owner = this.clinicService.findOwnerById(ownerId);
540	        if (owner == null) {
541	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
542	        }
543	        this.clinicService.deleteOwner(owner);
544	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
545	    }
546	
547	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
548	    @Override
549	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
550	        Owner owner = this.clinicService.findOwnerById(ownerId);
551	        if (owner == null) {
552	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
553	        }
554	        HttpHeaders headers = new HttpHeaders();
555	        Pet pet = petMapper.toPet(petFieldsDto);
556	        owner.setId(ownerId);
557	        pet.setOwner(owner);
558	        pet.getType().setName(null);
559	        this.clinicService.savePet(pet);
560	        PetDto petDto = petMapper.toPetDto(pet);
561	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
562	            .buildAndExpand(pet.getId()).toUri());
563	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
564	    }
565	
566	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
567	    @Override
568	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
569	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
570	        if (currentOwner != null) {
571	            Pet currentPet = this.clinicService.findPetById(petId);
572	            if (currentPet != null) {
573	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
574	                currentPet.setName(petFieldsDto.getName());
575	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
576	                this.clinicService.savePet(currentPet);
577	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
578	            }
579	        }
580	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
581	    }
582	
583	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
584	    @Override
585	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
586	        HttpHeaders headers = new HttpHeaders();
587	        Visit visit = visitMapper.toVisit(visitFieldsDto);
588	        Pet pet = new Pet();
589	        pet.setId(petId);
590	        visit.setPet(pet);
591	        this.clinicService.saveVisit(visit);
592	        VisitDto visitDto = visitMapper.toVisitDto(visit);
593	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
594	            .buildAndExpand(visit.getId()).toUri());
595	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
596	    }
597	
598	
599	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
600	    @Override
601	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
602	        Owner owner = this.clinicService.findOwnerById(ownerId);
603	        if (owner != null) {
604	            Pet pet = owner.getPet(petId);
605	            if (pet != null) {
606	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
607	            }
608	        }
